import sys, random, time; sys.path.insert(0,'/workspace/submission')
sys.path.insert(0,'/workspace/vendor/networkx-3.4.2-py3-none-any.whl')
from fcflow import FlowGraph
import networkx as nx
random.seed(7)
bad=0
for trial in range(400):
    n=random.randint(3,9); G=nx.DiGraph(); G.add_nodes_from(range(n)); g=FlowGraph(n)
    for u in range(n):
        for v in range(n):
            if u!=v and random.random()<0.4:
                c=random.randint(0,10); g.add_arc(u,v,c); G.add_edge(u,v,capacity=c)
    f,S=g.maxflow(0,n-1,want_cut=True)
    cutv=sum(d for u,v,d in G.edges(data='capacity') if S[u] and not S[v])
    f2=nx.maximum_flow_value(G,0,n-1)
    if cutv!=f or f!=f2 or S[0]!=True or S[n-1]!=False: bad+=1; print('bad',trial,f,f2,cutv)
    if g.cap!=g.src: print('restore fail')
print('bad',bad)
# timing on realistic shapes: 50 nodes, 256 arcs, big caps
random.seed(3)
for trial,(n,m) in enumerate([(50,256),(34,400),(50,128)]):
    t0=time.time()
    for _ in range(300):
        g=FlowGraph(n)
        pairs=random.sample([(u,v) for u in range(n) for v in range(n) if u<v], m//2)
        for (u,v) in pairs:
            c=random.randint(0,10**18); g.add_arc(u,v,c); g.add_arc(v,u,c)
        g.maxflow(0,n-1)
    print(n,m,'300 flows: %.2fs'%(time.time()-t0))
